vector<string> _SpeechCommands::SpellCheckCommand(vector<string> words)
{
    string model = llm_model;
    //string text = _Utilities::StringArray2String(words);
    string prompt = "If you would please spell check the following command and output only the command: ";
    for (int x = 0; x <= words.size(); x++)
    {
		prompt += words[x];
		prompt += " ";
    }
    string response = _LLM2::OllamaAPI(model, prompt, "NULL");
    response = _Parsers::LLM::json_parser(response);
    words = _Utilities::String2Words(response);
    words = _Utilities::RemovePunctuationArr(words);
    words = _Utilities::ArrayOfStringsToLowercase(words);
    string result = _Utilities::StringArray2String(words);
    _WorkingMemory::wm_llm_history_funct(prompt, result);

    return words;
}

// We need to make sure that grammar checking does not change the meaning of the command
vector<string> _SpeechCommands::GrammarCheckCommand(vector<string> words)
{
    string model = llm_model;
    //string text = _Utilities::StringArray2String(words);
    string prompt = "If you would please fix the grammar of the following command and output only the command: ";
    for (int x = 0; x <= words.size(); x++)
    {
        prompt += words[x];
        prompt += " ";
    }
    string response = _LLM2::OllamaAPI(model, prompt, "NULL");
    response = _Parsers::LLM::json_parser(response);
    words = _Utilities::String2Words(response);
    words = _Utilities::RemovePunctuationArr(words);
    words = _Utilities::ArrayOfStringsToLowercase(words);
    string result = _Utilities::StringArray2String(words);
    _WorkingMemory::wm_llm_history_funct(prompt, result);

    return words;
}

