vector<string> _SpeechCommands::SuggestCommands(vector<string> words)
{
    // Load full list of commands
    // Based on text have the LLM Suggest commands to perform
    // Wrote make a list of commands with some substitution and then include them into the prompt

    string model = llm_model;
    string prompt = "Please suggest ten commands to run based on the following text and the commands in the list following list of commands and use and please output only the suggested commands: ";

    for (int x = 0; x <= words.size(); x++)
    {
        prompt += words[x];
        prompt += " ";
    }

    string response = _LLM2::OllamaAPI(model, prompt, "NULL");
    response = _Parsers::LLM::json_parser(response);
    // Parse the commands
    vector<string> commands = _Parsers::ParseCommands(response);
    _WorkingMemory::wm_llm_history_funct(prompt, response);
    // Save the string to database

    return commands;
}

