// Function pointer type for the callback function
typedef void (*CallbackFunction)(const std::string&);

// Example callback function
void _SpeechCommands::myCallback(const std::string& str)
{
    vector<string> command = _Utilities::String2Words(str);
    cout << "Recieved String from LUA: " << str << endl;
    _SpeechCommands::SpeechCommands(command);
}

// Lua binding function to call the C++ callback function
int _SpeechCommands::lua_callback(lua_State* L)
{
    const char* str = luaL_checkstring(L, 1);
    CallbackFunction cb = static_cast<CallbackFunction>(lua_touserdata(L, lua_upvalueindex(1)));
    (*cb)(str);
    return 0;
}

// Function to execute the Lua script
void _SpeechCommands::executeLuaScript(lua_State* L, string scriptPath)
{
    // Load the Lua script from file
    if (luaL_dofile(L, scriptPath.c_str()))
    {
        std::cerr << "Error loading Lua script: " << lua_tostring(L, -1) << std::endl;
        lua_pop(L, 1); // Remove error message from stack
        return;
    }
}